apply.script:
$clase = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
function Get-Placas([string]$patron) {
  Get-ChildItem -Path $clase -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
    $p = Get-ItemProperty -Path $_.PSPath -ErrorAction SilentlyContinue
    if ($p -and (('' + $p.ProviderName + ' ' + $p.DriverDesc) -match $patron)) { $_.PSPath }
  }
}
function Poner([string]$ruta, [string]$nombre, $valor) {
  if (-not (Test-Path $ruta)) { New-Item -Path $ruta -Force | Out-Null }
  Set-ItemProperty -Path $ruta -Name $nombre -Type DWord -Value $valor -ErrorAction SilentlyContinue
}
function Sacar([string]$ruta, [string]$nombre) {
  if (Test-Path $ruta) { Remove-ItemProperty -Path $ruta -Name $nombre -ErrorAction SilentlyContinue }
}

$placas = @(Get-Placas 'AMD|Radeon|Advanced Micro|ATI Technologies')
if ($placas.Count -eq 0) { Write-Output 'ERROR: No se encontró una placa de video AMD Radeon en esta PC.'; exit 0 }
foreach ($p in $placas) {
  Set-ItemProperty -Path $p -Name 'EnableUlps' -Type DWord -Value 0 -ErrorAction SilentlyContinue
  if ((Get-ItemProperty -Path $p -ErrorAction SilentlyContinue).PSObject.Properties.Name -contains 'EnableUlps_NA') {
    Set-ItemProperty -Path $p -Name 'EnableUlps_NA' -Type String -Value '0' -ErrorAction SilentlyContinue
  }
}
Write-Output ('OK ' + $placas.Count)
exit 0

