foreach ($par in $opciones.GetEnumerator()) { $t += $par.Key + '=' + $par.Value + ';' }
if ($t -eq '') { Remove-ItemProperty -Path $ruta -Name DirectXUserGlobalSettings -ErrorAction SilentlyContinue }
else { Set-ItemProperty -Path $ruta -Name DirectXUserGlobalSettings -Value $t }
exit 0

