apply.script:
$tocados = 0
foreach ($dev in (Get-PnpDevice -Class Display -Status OK -ErrorAction SilentlyContinue)) {
  $ruta = 'HKLM:\SYSTEM\CurrentControlSet\Enum\' + $dev.InstanceId + '\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties'
  if (Test-Path $ruta) {
    Set-ItemProperty -Path $ruta -Name MSISupported -Type DWord -Value 1 -ErrorAction SilentlyContinue
    $tocados++
  }
}
if ($tocados -eq 0) { Write-Output 'ERROR: no se encontro ninguna placa de video que soporte MSI.' }
else { Write-Output ('OK ' + $tocados) }
exit 0

