apply.script:
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

[StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
public struct DEVMODE {
  [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmDeviceName;
  public short dmSpecVersion; public short dmDriverVersion; public short dmSize;
  public short dmDriverExtra; public int dmFields;
  public int dmPositionX; public int dmPositionY; public int dmDisplayOrientation; public int dmDisplayFixedOutput;
  public short dmColor; public short dmDuplex; public short dmYResolution; public short dmTTOption;
  public short dmCollate; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmFormName;
  public short dmLogPixels; public int dmBitsPerPel; public int dmPelsWidth; public int dmPelsHeight;
  public int dmDisplayFlags; public int dmDisplayFrequency;
  public int dmICMMethod; public int dmICMIntent; public int dmMediaType; public int dmDitherType;
  public int dmReserved1; public int dmReserved2; public int dmPanningWidth; public int dmPanningHeight;
}

public class Pantalla {
  [DllImport("user32.dll", CharSet = CharSet.Unicode)]
  public static extern bool EnumDisplaySettings(string deviceName, int modeNum, ref DEVMODE devMode);
  [DllImport("user32.dll", CharSet = CharSet.Unicode)]
  public static extern int ChangeDisplaySettingsEx(string lpszDeviceName, ref DEVMODE lpDevMode, IntPtr hwnd, int dwflags, IntPtr lParam);
}
'@

$ACTUAL = -1
$APLICAR = 0x00000001      # CDS_UPDATEREGISTRY
$SOLO_PROBAR = 0x00000002  # CDS_TEST
$cambiados = @()
$sinCambio = @()

# En vez de enumerar dispositivos (la API para eso no se lleva bien con
# PowerShell), se prueban los nombres que Windows usa siempre: \.DISPLAY1,
# DISPLAY2, etc. Los que no existen simplemente no responden.
for ($i = 1; $i -le 8; $i++) {
  $barra = [string][char]92
  $nombre = $barra + $barra + '.' + $barra + 'DISPLAY' + $i

  $modo = New-Object DEVMODE
  $modo.dmSize = [int16][System.Runtime.InteropServices.Marshal]::SizeOf($modo)
  if (-not [Pantalla]::EnumDisplaySettings($nombre, $ACTUAL, [ref]$modo)) { continue }
  # Una pantalla apagada o no conectada devuelve datos vacíos.
  if ($modo.dmPelsWidth -eq 0 -or $modo.dmDisplayFrequency -eq 0) { continue }

  $ancho = $modo.dmPelsWidth
  $alto = $modo.dmPelsHeight
  $bits = $modo.dmBitsPerPel
  $hzActual = $modo.dmDisplayFrequency
  $hzMaximo = $hzActual

  # Recorrer todos los modos que soporta y quedarse con la frecuencia más
  # alta DE ESTA MISMA resolución (cambiar la resolución sería una sorpresa
  # desagradable para el usuario).
  $j = 0
  while ($true) {
    $prueba = New-Object DEVMODE
    $prueba.dmSize = [int16][System.Runtime.InteropServices.Marshal]::SizeOf($prueba)
    if (-not [Pantalla]::EnumDisplaySettings($nombre, $j, [ref]$prueba)) { break }
    if ($prueba.dmPelsWidth -eq $ancho -and $prueba.dmPelsHeight -eq $alto -and $prueba.dmBitsPerPel -eq $bits) {
      if ($prueba.dmDisplayFrequency -gt $hzMaximo) { $hzMaximo = $prueba.dmDisplayFrequency }
    }
    $j++
  }

  if ($hzMaximo -gt $hzActual) {
    $modo.dmDisplayFrequency = $hzMaximo
    $modo.dmFields = 0x400000  # DM_DISPLAYFREQUENCY
    # Primero se consulta si el driver acepta el cambio; recién ahí se aplica.
    if ([Pantalla]::ChangeDisplaySettingsEx($nombre, [ref]$modo, [IntPtr]::Zero, $SOLO_PROBAR, [IntPtr]::Zero) -eq 0) {
      $resultado = [Pantalla]::ChangeDisplaySettingsEx($nombre, [ref]$modo, [IntPtr]::Zero, $APLICAR, [IntPtr]::Zero)
      if ($resultado -eq 0) { $cambiados += ('Pantalla ' + $i + ': ' + $hzActual + ' -> ' + $hzMaximo + ' Hz') }
      else { $sinCambio += ('Pantalla ' + $i + ': el driver rechazo ' + $hzMaximo + ' Hz') }
    } else {
      $sinCambio += ('Pantalla ' + $i + ': el driver rechazo ' + $hzMaximo + ' Hz')
    }
  } else {
    $sinCambio += ('Pantalla ' + $i + ': ya esta al maximo (' + $hzActual + ' Hz)')
  }
}

if ($cambiados.Count -gt 0) { Write-Output ('OK ' + ($cambiados -join ' | ')) }
elseif ($sinCambio.Count -gt 0) { Write-Output ('SIN CAMBIOS ' + ($sinCambio -join ' | ')) }
else { Write-Output 'SIN CAMBIOS No se detecto ninguna pantalla activa.' }
exit 0

