apply.script:
$cands = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.PhysicalMediaType -eq '802.3' -or $_.NdisPhysicalMedium -eq 14 } | Sort-Object @{ Expression = { $_.Status -eq 'Up' }; Descending = $true }
if (-not $cands) { throw 'No se encontró ninguna placa de red por cable (las VPN y las placas virtuales no cuentan).' }
$adapter = $null; $prop = $null
foreach ($c in $cands) {
  $p = Get-NetAdapterAdvancedProperty -Name $c.Name -ErrorAction SilentlyContinue |
    Where-Object { $_.RegistryKeyword -match '^\*?SpeedDuplex$' -or $_.DisplayName -match 'Speed.*Duplex|Velocidad.*D.plex' } |
    Select-Object -First 1
  if ($p) { $adapter = $c; $prop = $p; break }
}
if (-not $prop) { throw 'Tu placa de red no tiene la opción "Velocidad y Dúplex" (Speed & Duplex). Pasa con algunas placas USB.' }
$target = $prop.ValidDisplayValues | Where-Object { $_ -match '1\.0 ?Gbps.*(Full|Completo|D.plex)' -or $_ -match '1000.*(Full|Completo)' } | Select-Object -First 1
if (-not $target) { throw 'Esta placa no ofrece la opción de 1 Gbps Full Duplex entre sus valores disponibles.' }
Set-NetAdapterAdvancedProperty -Name $adapter.Name -DisplayName $prop.DisplayName -DisplayValue $target
# Reiniciar la placa (deshabilitar/habilitar) para que el cambio de
# velocidad tome efecto de una — sin esto a veces queda "pedido" pero
# no aplicado hasta el próximo reinicio de Windows. El corte de unos
# segundos es esperado y normal.
Disable-NetAdapter -Name $adapter.Name -Confirm:$false
Start-Sleep -Seconds 2
Enable-NetAdapter -Name $adapter.Name -Confirm:$false

$hechos = 0
foreach ($n in (Get-NetAdapter | Where-Object { $_.Status -eq 'Up' })) {
  foreach ($par in @(@('*InterruptModeration',0), @('*FlowControl',0), @('*LsoV2IPv4',0), @('*LsoV2IPv6',0))) {
    try {
      Set-NetAdapterAdvancedProperty -Name $n.Name -RegistryKeyword $par[0] -RegistryValue $par[1] -NoRestart -ErrorAction Stop
      $hechos++
    } catch { }
  }
}
if ($hechos -eq 0) { Write-Output 'ERROR: ninguna placa de red aceptó estos ajustes (el driver no los expone).' }
else { Write-Output ('OK ' + $hechos) }

