apply.script:
$ram = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 0)
# Con mucha RAM no hace falta un archivo enorme: alcanza para los volcados
# y para las apps que exigen tenerlo si o si (varios juegos lo hacen).
if ($ram -ge 32) { $tam = 4096 } elseif ($ram -ge 16) { $tam = 6144 } else { $tam = 8192 }
# Antes el máximo era igual al inicial (4 a 8 GB fijos): con un juego
# pesado y OBS abiertos se agotaba la memoria y se cerraban programas.
# Ahora arranca en ese tamaño pero puede crecer.
$max = [int][math]::Min(32768, [math]::Max(16384, $ram * 1024))

$cs = Get-CimInstance Win32_ComputerSystem
if ($cs.AutomaticManagedPagefile) {
  Set-CimInstance -InputObject $cs -Property @{ AutomaticManagedPagefile = $false } | Out-Null
}
$pf = Get-CimInstance Win32_PageFileSetting -Filter "Name='C:\\pagefile.sys'" -ErrorAction SilentlyContinue
if ($pf) {
  Set-CimInstance -InputObject $pf -Property @{ InitialSize = $tam; MaximumSize = $max } | Out-Null
} else {
  New-CimInstance -ClassName Win32_PageFileSetting -Property @{ Name = 'C:\\pagefile.sys'; InitialSize = $tam; MaximumSize = $max } | Out-Null
}
Write-Output ('OK ' + $tam + '-' + $max + ' MB')
exit 0

