Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class MuraMouseNative {
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, int[] pvParam, uint fWinIni);
}
'@ -ErrorAction SilentlyContinue
function Set-MouseParams($speed, $t1, $t2) {
  [MuraMouseNative]::SystemParametersInfo(4, 0, @($t1, $t2, $speed), 3) | Out-Null
}
# Aceleración de "Teclas de mouse" (Accesibilidad): tiempo en ms hasta la
# velocidad máxima, 5000 = barra al mínimo ("Lenta"), 3000 = de fábrica. Se
# lee la estructura MOUSEKEYS entera (cbSize, flags, velocidad máx, tiempo,
# ...) y solo se cambia el tiempo, así no se prende ni apaga la función.
function Set-MouseKeysAccel($ms) {
  $mk = New-Object int[] 7
  $mk[0] = 28
  if ([MuraMouseNative]::SystemParametersInfo(54, 28, $mk, 0)) {
    $mk[3] = $ms
    [MuraMouseNative]::SystemParametersInfo(55, 28, $mk, 3) | Out-Null
  }
}
 Set-MouseParams 0 0 0; Set-MouseKeysAccel 5000

