apply.script:
$base = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render'
$n = 0
# Detección de chasis portátil para no romper parlantes integrados
$esLaptop = $false
try {
  $chassis = (Get-CimInstance Win32_SystemEnclosure -ErrorAction SilentlyContinue).ChassisTypes
  if ($chassis -and ($chassis | Where-Object { $_ -in 8,9,10,11,12,14,18,21,30,31,32 })) { $esLaptop = $true }
} catch {}

foreach ($dev in (Get-ChildItem $base -ErrorAction SilentlyContinue)) {
  $props = Join-Path $dev.PSPath 'Properties'
  $nombreDev = ''
  if (Test-Path $props) {
    $nombreDev = (Get-ItemProperty -Path $props -Name '{a45c254e-df1c-4efd-8020-67d146a850e0},2' -ErrorAction SilentlyContinue).'{a45c254e-df1c-4efd-8020-67d146a850e0},2'
  }
  # Si es laptop y es el parlante interno / Realtek / Intel SST, no desactivar mejoras porque cuelga AudioEndpointBuilder
  if ($esLaptop -and ($nombreDev -match 'Realtek|Intel|Speakers|Altavoces|Internal|SST|Synaptics|Conexant|Senary')) {
    continue
  }
  $fx = Join-Path $dev.PSPath 'FxProperties'
  if (-not (Test-Path $fx)) { New-Item -Path $fx -Force | Out-Null }
  # Propiedad "deshabilitar mejoras" del endpoint de audio
  Set-ItemProperty -Path $fx -Name '{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},5' -Type DWord -Value 1 -ErrorAction SilentlyContinue
  $n++
}

# Siempre asegurar que AudioEndpointBuilder y Audiosrv estén en Automatic
foreach ($s in 'AudioEndpointBuilder','Audiosrv') {
  $srv = Get-Service -Name $s -ErrorAction SilentlyContinue
  if ($srv -and $srv.StartType -ne 'Automatic') {
    Set-Service -Name $s -StartupType Automatic -ErrorAction SilentlyContinue
  }
  if ($srv -and $srv.Status -ne 'Running') {
    Start-Service -Name $s -ErrorAction SilentlyContinue
  }
}
Write-Output ('OK ' + $n)
exit 0

