apply.script:
$lineas = @()
$lineas += 'DIAGNOSTICO DE BIOS Y HARDWARE - MuraTweaks'
$lineas += ('Generado: ' + (Get-Date).ToString('dd/MM/yyyy HH:mm'))
$lineas += ''

$bios = Get-CimInstance Win32_BIOS -ErrorAction SilentlyContinue
$placa = Get-CimInstance Win32_BaseBoard -ErrorAction SilentlyContinue
$lineas += '== PLACA Y BIOS =='
if ($placa) { $lineas += ('Placa madre: ' + $placa.Manufacturer + ' ' + $placa.Product) }
if ($bios) {
  $lineas += ('Version de BIOS: ' + $bios.SMBIOSBIOSVersion)
  $fecha = $bios.ReleaseDate
  if ($fecha) { $lineas += ('Fecha de la BIOS: ' + ([datetime]$fecha).ToString('dd/MM/yyyy')) }
  $lineas += ('Modo de arranque: ' + $(if ($env:firmware_type) { $env:firmware_type } else { 'desconocido' }))
}
$lineas += ''

$lineas += '== MEMORIA RAM =='
$modulos = Get-CimInstance Win32_PhysicalMemory -ErrorAction SilentlyContinue
$xmpDudoso = $false
foreach ($m in $modulos) {
  $marca = if ($m.Manufacturer) { $m.Manufacturer.Trim() } else { 'sin marca' }
  $gb = [math]::Round($m.Capacity / 1GB, 0)
  $lineas += ('Modulo en ' + $m.BankLabel + ' / ' + $m.DeviceLocator + ': ' + $gb + ' GB ' + $marca + ' | velocidad configurada: ' + $m.ConfiguredClockSpeed + ' MHz | maxima del modulo: ' + $m.Speed + ' MHz')
  if ($m.ConfiguredClockSpeed -and $m.Speed -and $m.ConfiguredClockSpeed -lt $m.Speed) { $xmpDudoso = $true }
}
if ($xmpDudoso) {
  $lineas += ''
  $lineas += '  >> La RAM esta corriendo MAS LENTO de lo que soporta. Falta activar el perfil'
  $lineas += '     XMP (Intel) o EXPO/DOCP (AMD) en la BIOS. Es la mejora gratis mas grande'
  $lineas += '     que podes hacerle a la PC.'
} else {
  $lineas += ''
  $lineas += '  >> La RAM corre a su velocidad nominal (XMP/EXPO parece activo).'
}
$lineas += ''

$lineas += '== CPU Y VIRTUALIZACION =='
$cpu = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1
if ($cpu) {
  $lineas += ('Procesador: ' + $cpu.Name.Trim())
  $lineas += ('Nucleos / hilos: ' + $cpu.NumberOfCores + ' / ' + $cpu.NumberOfLogicalProcessors)
  $lineas += ('Virtualizacion habilitada en la BIOS: ' + $(if ($cpu.VirtualizationFirmwareEnabled) { 'SI' } else { 'NO (activar SVM / VT-x si usas maquinas virtuales o emuladores)' }))
}
$dg = Get-CimInstance -ClassName Win32_DeviceGuard -Namespace root\Microsoft\Windows\DeviceGuard -ErrorAction SilentlyContinue
if ($dg) {
  $vbs = $dg.VirtualizationBasedSecurityStatus
  $lineas += ('VBS (seguridad basada en virtualizacion): ' + $(if ($vbs -eq 2) { 'ACTIVA - le saca algo de rendimiento a los juegos' } elseif ($vbs -eq 1) { 'habilitada pero no corriendo' } else { 'desactivada' }))
}
$lineas += ''

$lineas += '== ARRANQUE SEGURO Y TPM =='
try {
  $sb = Confirm-SecureBootUEFI -ErrorAction Stop
  $lineas += ('Secure Boot: ' + $(if ($sb) { 'activado' } else { 'desactivado' }))
} catch {
  $lineas += 'Secure Boot: no se pudo leer (hace falta admin, o la BIOS esta en modo Legacy/CSM)'
}
try {
  $tpm = Get-Tpm -ErrorAction Stop
  $lineas += ('TPM presente: ' + $(if ($tpm.TpmPresent) { 'si' } else { 'no' }) + ' | listo: ' + $(if ($tpm.TpmReady) { 'si' } else { 'no' }))
} catch {
  $lineas += 'TPM: no se pudo leer'
}
$lineas += ''

$lineas += '== GRAFICA =='
foreach ($g in (Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue)) {
  $vram = if ($g.AdapterRAM -gt 0) { [math]::Round($g.AdapterRAM / 1GB, 1).ToString() + ' GB' } else { 'desconocida' }
  $lineas += ($g.Name + ' | driver ' + $g.DriverVersion + ' del ' + $(if ($g.DriverDate) { ([datetime]$g.DriverDate).ToString('dd/MM/yyyy') } else { '?' }) + ' | VRAM reportada: ' + $vram)
}
$lineas += ''

$lineas += '== DISCOS =='
foreach ($d in (Get-PhysicalDisk -ErrorAction SilentlyContinue)) {
  $tam = [math]::Round($d.Size / 1GB, 0)
  $lineas += ($d.FriendlyName + ' | ' + $d.MediaType + ' | bus ' + $d.BusType + ' | ' + $tam + ' GB')
}
$lineas += ''
$lineas += 'Nota: nada de esto se puede cambiar desde Windows. Con esta info sabes que'
$lineas += 'tocar cuando entres a la BIOS (podes hacerlo con el tweak "Reiniciar directo'
$lineas += 'a la BIOS", sin adivinar la tecla).'

$destino = Join-Path ([Environment]::GetFolderPath('Desktop')) 'MuraTweaks - Diagnostico de BIOS.txt'
Set-Content -Path $destino -Value $lineas -Encoding UTF8
Start-Process notepad.exe $destino
Write-Output ('OK ' + $destino)
exit 0
